import { Request, Response, NextFunction } from 'express'
import { createError } from './errorHandler'
import { supabase } from '../lib/supabase'
import { getUserRolesAndPermissions } from '../modules/iam/service'
type UserRole = 'admin' | 'mitarbeiter' | 'kunde' | 'viewer'

/**
 * Auth Middleware – validiert JWT Token aus Authorization Header
 * Setzt req.user und req.userId für nachfolgende Handler
 * Lädt Rollen + Permissions aus der Datenbank
 *
 * Usage: router.get('/geschuetzt', authMiddleware, handler)
 */
export async function authMiddleware(
  req: Request,
  _res: Response,
  next: NextFunction
): Promise<void> {
  try {
    const authHeader = req.headers.authorization
    if (!authHeader?.startsWith('Bearer ')) {
      return next(createError('Kein Token angegeben', 401))
    }

    const token = authHeader.split(' ')[1]

    const { data: { user }, error } = await supabase.auth.getUser(token)

    if (error || !user) {
      return next(createError('Ungültiger oder abgelaufener Token', 401))
    }

    // Rollen + Permissions aus DB laden
    let roles: string[] = []
    let permissions: string[] = []
    try {
      const result = await getUserRolesAndPermissions(user.id)
      roles = result.roles
      permissions = result.permissions
    } catch {
      // Falls IAM-Tabellen noch nicht existieren: Fallback auf user_metadata
      const metaRole = (user.user_metadata?.role as string) ?? 'viewer'
      roles = [metaRole]
    }

    const primaryRole = (roles[0] ?? 'viewer') as UserRole

    req.userId = user.id
    req.user   = {
      id:            user.id,
      email:         user.email ?? '',
      role:          primaryRole,
      roles,
      permissions,
      isActive:      true,
      emailVerified: !!user.email_confirmed_at,
      createdAt:     user.created_at,
      updatedAt:     user.updated_at ?? user.created_at,
    }

    next()
  } catch {
    next(createError('Auth-Fehler', 401))
  }
}

/**
 * Admin-Only Middleware – nur nach authMiddleware verwenden
 */
export function adminMiddleware(
  req: Request,
  _res: Response,
  next: NextFunction
): void {
  if (req.user?.role !== 'admin') {
    return next(createError('Kein Zugriff – Admin erforderlich', 403))
  }
  next()
}

/**
 * Permission-Check Middleware Factory
 * Usage: router.get('/kpis', authMiddleware, requirePermission('module:kpis:read'), handler)
 */
export function requirePermission(permission: string) {
  return (req: Request, _res: Response, next: NextFunction): void => {
    if (!req.user) {
      return next(createError('Nicht authentifiziert', 401))
    }
    // Admins haben immer Zugriff
    if (req.user.roles.includes('admin')) {
      return next()
    }
    if (!req.user.permissions.includes(permission)) {
      return next(createError(`Berechtigung '${permission}' fehlt`, 403))
    }
    next()
  }
}
